// AppendJSON appends the JSON encoding of m to b.
func (m *SubscribeResult) AppendJSON(b []byte) []byte {
	s := len(b)
	if m.Expires {
		b = append(b, ",\"expires\":true"...)
	}
	if m.Ttl != 0 {
		b = append(b, ",\"ttl\":"...)
		b = cfjson.AppendUint(b, uint64(m.Ttl))
	}
	if m.Recoverable {
		b = append(b, ",\"recoverable\":true"...)
	}
	if m.Epoch != "" {
		b = append(b, ",\"epoch\":"...)
		b = cfjson.AppendString(b, m.Epoch)
	}
	if len(m.Publications) != 0 {
		b = append(b, ",\"publications\":"...)
		b = append(b, '[')
		for n1, e2 := range m.Publications {
			if n1 != 0 {
				b = append(b, ',')
			}
			if e2 == nil {
				b = append(b, "null"...)
			} else {
				b = e2.AppendJSON(b)
			}
		}
		b = append(b, ']')
	}
	if m.Recovered {
		b = append(b, ",\"recovered\":true"...)
	}
	if m.Offset != 0 {
		b = append(b, ",\"offset\":"...)
		b = cfjson.AppendUint(b, m.Offset)
	}
	if m.Positioned {
		b = append(b, ",\"positioned\":true"...)
	}
	if len(m.Data) != 0 {
		b = append(b, ",\"data\":"...)
		b = cfjson.AppendRaw(b, m.Data)
	}
	if m.WasRecovering {
		b = append(b, ",\"was_recovering\":true"...)
	}
	if m.Delta {
		b = append(b, ",\"delta\":true"...)
	}
	if m.Id != 0 {
		b = append(b, ",\"id\":"...)
		b = cfjson.AppendInt(b, m.Id)
	}
	if m.Type != 0 {
		b = append(b, ",\"type\":"...)
		b = cfjson.AppendInt(b, int64(m.Type))
	}
	if m.Phase != 0 {
		b = append(b, ",\"phase\":"...)
		b = cfjson.AppendInt(b, int64(m.Phase))
	}
	if m.Cursor != "" {
		b = append(b, ",\"cursor\":"...)
		b = cfjson.AppendString(b, m.Cursor)
	}
	if len(m.State) != 0 {
		b = append(b, ",\"state\":"...)
		b = append(b, '[')
		for n3, e4 := range m.State {
			if n3 != 0 {
				b = append(b, ',')
			}
			if e4 == nil {
				b = append(b, "null"...)
			} else {
				b = e4.AppendJSON(b)
			}
		}
		b = append(b, ']')
	}
	if m.PublishDebounce != 0 {
		b = append(b, ",\"publish_debounce\":"...)
		b = cfjson.AppendUint(b, uint64(m.PublishDebounce))
	}
	if len(b) == s {
		return append(b, '{', '}')
	}
	b[s] = '{'
	return append(b, '}')
}

