func (m *FilterNode) AppendJSON(b []byte) []byte {
	s := len(b)
	if m.Op != "" {
		b = append(b, ",\"op\":"...)
		b = cfjson.AppendString(b, m.Op)
	}
	if m.Key != "" {
		b = append(b, ",\"key\":"...)
		b = cfjson.AppendString(b, m.Key)
	}
	if m.Cmp != "" {
		b = append(b, ",\"cmp\":"...)
		b = cfjson.AppendString(b, m.Cmp)
	}
	if m.Val != "" {
		b = append(b, ",\"val\":"...)
		b = cfjson.AppendString(b, m.Val)
	}
	if len(m.Vals) != 0 {
		b = append(b, ",\"vals\":"...)
		b = append(b, '[')
		for n1, e2 := range m.Vals {
			if n1 != 0 {
				b = append(b, ',')
			}
			b = cfjson.AppendString(b, e2)
		}
		b = append(b, ']')
	}
	if len(m.Nodes) != 0 {
		b = append(b, ",\"nodes\":"...)
		b = append(b, '[')
		for n3, e4 := range m.Nodes {
			if n3 != 0 {
				b = append(b, ',')
			}
			if e4 == nil {
				b = append(b, "null"...)
			} else {
				b = e4.AppendJSON(b)
			}
		}
		b = append(b, ']')
	}
	if len(b) == s {
		return append(b, '{', '}')
	}
	b[s] = '{'
	return append(b, '}')
}

